// Generates src/generated/keys.ts from the en catalogs (ADR 0046 D6,
// change 4): every usable en key as "namespace:key" with the kinds of its
// ICU arguments. Pure and deterministic: namespaces in NAMESPACES order,
// keys and argument names sorted. scripts/gen-keys.mjs writes the result;
// i18n:check fails when the committed file differs.
import { usableEnSignature } from "./check.ts";
import type { ArgKind } from "./icu.ts";
import { NAMESPACES } from "./locale.ts";

/** The generated file's argument kinds. */
type GeneratedKind = "string" | "select" | "number";

const KIND: Readonly<Partial<Record<ArgKind, GeneratedKind>>> = {
  string: "string",
  select: "select",
  number: "number",
  plural: "number",
  selectordinal: "number",
};

const HEADER = `// Generated by scripts/gen-keys.mjs from locales/en/*.json (ADR 0046).
// Do not edit: run \`pnpm --filter @bricx/i18n gen:keys\`. i18n:check fails
// when this file is stale.

/** ICU argument kinds: "string" (simple), "select", "number" (number, plural, selectordinal). */
export type ArgKind = "string" | "select" | "number";
`;

const byCodeUnit = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);

export function generateKeysModule(
  en: Readonly<Record<string, Readonly<Record<string, unknown>>>>,
): string {
  const lines: string[] = [];
  for (const namespace of NAMESPACES) {
    const catalog = en[namespace];
    if (catalog === undefined) continue;
    for (const key of Object.keys(catalog).sort(byCodeUnit)) {
      const signature = usableEnSignature(key, catalog[key]);
      if (signature === undefined) continue;
      const args = Object.keys(signature.args)
        .sort(byCodeUnit)
        .map((name) => {
          const kind = signature.args[name];
          return `${name}: "${kind === undefined ? "string" : (KIND[kind] ?? "string")}"`;
        });
      const body = args.length === 0 ? "{}" : `{ ${args.join(", ")} }`;
      lines.push(`  "${namespace}:${key}": ${body},`);
    }
  }
  return `${HEADER}
export const MESSAGE_ARGS = {
${lines.join("\n")}
} as const satisfies Readonly<Record<string, Readonly<Record<string, ArgKind>>>>;

export type MessageKey = keyof typeof MESSAGE_ARGS;
`;
}
